using System;
using PX.Data;
using PX.Data.BQL.Fluent;
using PX.Objects.PO;

namespace StudioB.Containers
{
    public class ContainerMaint : PXGraph<ContainerMaint, UsrContainer>
    {
        public static bool IsActive() => true;

        #region Views
        public SelectFrom<UsrContainer>.View Container;

        public SelectFrom<UsrContainerEvent>
            .Where<UsrContainerEvent.containerID.IsEqual<UsrContainer.containerID.FromCurrent>>
            .OrderBy<UsrContainerEvent.eventDateTime.Desc>
            .View Events;

        public SelectFrom<UsrContainerPOLink>
            .Where<UsrContainerPOLink.containerID.IsEqual<UsrContainer.containerID.FromCurrent>>
            .View POLinks;
        #endregion

        #region Actions
        public PXAction<UsrContainer> RefreshTracking;
        [PXButton(CommitChanges = true)]
        [PXUIField(DisplayName = "Refresh Tracking", MapEnableRights = PXCacheRights.Update)]
        protected void refreshTracking()
        {
            // Placeholder — tracking refresh triggered via API from webhook-router.
            // This action can be wired to call the carrier API directly in a future phase,
            // or to push a message to the webhook-router BullMQ queue.
            UsrContainer container = Container.Current;
            if (container == null) return;

            container.LastSyncDate = DateTime.UtcNow;
            Container.Update(container);
            Actions.PressSave();
        }
        #endregion

        #region Event Handlers
        protected void _(Events.RowSelected<UsrContainer> e)
        {
            if (e.Row == null) return;
            bool isActive = e.Row.Status != "DELIVERED" && e.Row.Status != "CANCELLED";
            PXUIFieldAttribute.SetEnabled<UsrContainer.containerCD>(e.Cache, e.Row, string.IsNullOrEmpty(e.Row.ContainerCD));
            RefreshTracking.SetEnabled(isActive);
        }
        #endregion

        #region Persist Override
        public override void Persist()
        {
            UsrContainer container = Container.Current;
            base.Persist();

            // After save, propagate ETA to linked PO headers and lines
            if (container?.ETA != null)
            {
                var poRefs = new System.Collections.Generic.List<Tuple<string, string, int?>>();
                foreach (UsrContainerPOLink link in POLinks.Select())
                {
                    poRefs.Add(Tuple.Create(link.OrderType, link.OrderNbr, link.LineNbr));
                }
                if (poRefs.Count > 0)
                {
                    ContainerDatePropagation.PropagateArrivalDate(container.ETA, poRefs);
                }
            }

            // Push container update to webhook-router for carrier event refresh
            if (container != null)
            {
                try
                {
                    var webhookUrl = System.Configuration.ConfigurationManager.AppSettings["ContainerWebhookUrl"];
                    if (!string.IsNullOrEmpty(webhookUrl))
                    {
                        var json = Newtonsoft.Json.JsonConvert.SerializeObject(new
                        {
                            ContainerCD = container.ContainerCD,
                            CarrierCode = container.CarrierCode,
                            ContainerID = container.ContainerID,
                            Status = container.Status,
                        });
                        using (var wc = new System.Net.WebClient())
                        {
                            wc.Headers[System.Net.HttpRequestHeader.ContentType] = "application/json";
                            wc.UploadStringAsync(new System.Uri(webhookUrl), "POST", json);
                        }
                    }
                }
                catch { /* Fire-and-forget — don't block save */ }
            }
        }
        #endregion
    }
}

using System;
using System.Configuration;
using System.Data.SqlClient;
using Customization;

namespace StudioB.Containers
{
    public class AesthetikContainersInstall : CustomizationPlugin
    {
        public override void UpdateDatabase()
        {
            try
            {
                var cs = ConfigurationManager.ConnectionStrings["ProjectX"];
                if (cs == null) { WriteLog("[AesthetikContainers] No ProjectX connection string — skipping DDL"); return; }
                string connStr = cs.ConnectionString + ";TrustServerCertificate=True";

                using (var conn = new SqlConnection(connStr))
                {
                    conn.Open();

                    // ── Container Tracking Tables ──────────────────────────────
                    EnsureTable(conn, "UsrContainer", @"
                        CompanyID int NOT NULL DEFAULT 0,
                        ContainerID int IDENTITY(1,1) NOT NULL,
                        ContainerCD nvarchar(20) NOT NULL,
                        CarrierCode nvarchar(20) NOT NULL DEFAULT 'OTHER',
                        BookingRef nvarchar(50) NULL,
                        BillOfLading nvarchar(50) NULL,
                        VesselName nvarchar(50) NULL,
                        VesselIMO nvarchar(10) NULL,
                        VoyageNbr nvarchar(30) NULL,
                        PortOfLoading nvarchar(10) NULL,
                        PortOfDischarge nvarchar(10) NULL,
                        ETD datetime NULL,
                        ATD datetime NULL,
                        ETA datetime NULL,
                        ATA datetime NULL,
                        Status nvarchar(20) NOT NULL DEFAULT 'BOOKED',
                        ContainerType nvarchar(10) NULL,
                        SealNbr nvarchar(20) NULL,
                        LastEventCode nvarchar(20) NULL,
                        LastEventDate datetime NULL,
                        LastSyncDate datetime NULL,
                        NoteID uniqueidentifier NULL,
                        CreatedByID uniqueidentifier NULL,
                        CreatedByScreenID char(8) NULL,
                        CreatedDateTime datetime NULL,
                        LastModifiedByID uniqueidentifier NULL,
                        LastModifiedByScreenID char(8) NULL,
                        LastModifiedDateTime datetime NULL,
                        tstamp timestamp NOT NULL,
                        CONSTRAINT PK_UsrContainer PRIMARY KEY (CompanyID, ContainerID)
                    ");

                    EnsureTable(conn, "UsrContainerEvent", @"
                        CompanyID int NOT NULL DEFAULT 0,
                        EventID int IDENTITY(1,1) NOT NULL,
                        ContainerID int NOT NULL,
                        CarrierEventCode nvarchar(20) NOT NULL DEFAULT '',
                        NormalizedEventCode nvarchar(20) NOT NULL DEFAULT '',
                        EventDateTime datetime NOT NULL DEFAULT GETUTCDATE(),
                        EventClassifier nvarchar(10) NULL,
                        LocationName nvarchar(100) NULL,
                        LocationCode nvarchar(10) NULL,
                        VesselName nvarchar(50) NULL,
                        Description nvarchar(255) NULL,
                        RawPayload nvarchar(MAX) NULL,
                        CreatedDateTime datetime NOT NULL DEFAULT GETUTCDATE(),
                        CONSTRAINT PK_UsrContainerEvent PRIMARY KEY (CompanyID, EventID)
                    ");

                    EnsureTable(conn, "UsrContainerPOLink", @"
                        CompanyID int NOT NULL DEFAULT 0,
                        LinkID int IDENTITY(1,1) NOT NULL,
                        ContainerID int NOT NULL,
                        OrderType nvarchar(2) NOT NULL DEFAULT 'RO',
                        OrderNbr nvarchar(15) NOT NULL DEFAULT '',
                        LineNbr int NULL,
                        CONSTRAINT PK_UsrContainerPOLink PRIMARY KEY (CompanyID, LinkID)
                    ");

                    // Indexes
                    EnsureIndex(conn, "UsrContainer", "IX_UsrContainer_ContainerCD", "CompanyID, ContainerCD");
                    EnsureIndex(conn, "UsrContainer", "IX_UsrContainer_Status", "CompanyID, Status");
                    EnsureIndex(conn, "UsrContainerEvent", "IX_UsrContainerEvent_ContainerID", "CompanyID, ContainerID, EventDateTime DESC");
                    EnsureIndex(conn, "UsrContainerPOLink", "IX_UsrContainerPOLink_ContainerID", "CompanyID, ContainerID");
                    EnsureIndex(conn, "UsrContainerPOLink", "IX_UsrContainerPOLink_PO", "CompanyID, OrderType, OrderNbr");

                    // SOShipment container fields
                    EnsureColumn(conn, "SOShipment", "UsrIncludeInContainer", "bit NULL DEFAULT 0");
                    EnsureColumn(conn, "SOShipment", "UsrContainerID", "int NULL");

                    // ── InventoryItem tariff/customs fields ────────────────────
                    EnsureColumn(conn, "InventoryItem", "UsrDutyRate", "decimal(25,4) NULL");
                    EnsureColumn(conn, "InventoryItem", "UsrFiberContent", "nvarchar(100) NULL");
                    EnsureColumn(conn, "InventoryItem", "UsrPreferentialTariff", "bit NULL");
                    EnsureColumn(conn, "InventoryItem", "UsrFreightClass", "nvarchar(15) NULL");

                    // ── POReceiptLine landed cost fields ───────────────────────
                    EnsureColumn(conn, "POReceiptLine", "UsrActualDutyAmt", "decimal(25,4) NULL");
                    EnsureColumn(conn, "POReceiptLine", "UsrActualFreightAmt", "decimal(25,4) NULL");
                    EnsureColumn(conn, "POReceiptLine", "UsrBrokerageAmt", "decimal(25,4) NULL");

                    // ── Freight Forwarders Table ──────────────────────────────
                    EnsureTable(conn, "UsrFreightForwarder", @"
                        CompanyID int NOT NULL DEFAULT 0,
                        ForwarderID int IDENTITY(1,1) NOT NULL,
                        ForwarderCD nvarchar(15) NOT NULL,
                        Name nvarchar(100) NOT NULL,
                        ContactName nvarchar(100) NULL,
                        Phone nvarchar(30) NULL,
                        Email nvarchar(100) NULL,
                        Website nvarchar(200) NULL,
                        CarrierAPIType nvarchar(20) NULL,
                        CarrierAPIKey nvarchar(200) NULL,
                        Active bit NOT NULL DEFAULT 1,
                        NoteID uniqueidentifier NULL,
                        CreatedByID uniqueidentifier NULL,
                        CreatedByScreenID char(8) NULL,
                        CreatedDateTime datetime NULL,
                        LastModifiedByID uniqueidentifier NULL,
                        LastModifiedByScreenID char(8) NULL,
                        LastModifiedDateTime datetime NULL,
                        tstamp timestamp NOT NULL,
                        CONSTRAINT PK_UsrFreightForwarder PRIMARY KEY (CompanyID, ForwarderID)
                    ");
                    EnsureIndex(conn, "UsrFreightForwarder", "IX_UsrFreightForwarder_CD", "CompanyID, ForwarderCD");

                    // ── Container Types Table ────────────────────────────────
                    EnsureTable(conn, "UsrContainerType", @"
                        CompanyID int NOT NULL DEFAULT 0,
                        ContainerTypeID int IDENTITY(1,1) NOT NULL,
                        TypeCD nvarchar(10) NOT NULL,
                        Description nvarchar(60) NULL,
                        LengthFt decimal(6,1) NULL,
                        WidthFt decimal(6,1) NULL,
                        HeightFt decimal(6,1) NULL,
                        MaxWeightKg decimal(10,0) NULL,
                        Active bit NOT NULL DEFAULT 1,
                        NoteID uniqueidentifier NULL,
                        CreatedByID uniqueidentifier NULL,
                        CreatedByScreenID char(8) NULL,
                        CreatedDateTime datetime NULL,
                        LastModifiedByID uniqueidentifier NULL,
                        LastModifiedByScreenID char(8) NULL,
                        LastModifiedDateTime datetime NULL,
                        tstamp timestamp NOT NULL,
                        CONSTRAINT PK_UsrContainerType PRIMARY KEY (CompanyID, ContainerTypeID)
                    ");
                    EnsureIndex(conn, "UsrContainerType", "IX_UsrContainerType_CD", "CompanyID, TypeCD");

                    // ── Ports Table ──────────────────────────────────────────
                    EnsureTable(conn, "UsrPort", @"
                        CompanyID int NOT NULL DEFAULT 0,
                        PortID int IDENTITY(1,1) NOT NULL,
                        PortCode nvarchar(10) NOT NULL,
                        PortName nvarchar(100) NOT NULL,
                        Country nvarchar(2) NULL,
                        Active bit NOT NULL DEFAULT 1,
                        NoteID uniqueidentifier NULL,
                        CreatedByID uniqueidentifier NULL,
                        CreatedByScreenID char(8) NULL,
                        CreatedDateTime datetime NULL,
                        LastModifiedByID uniqueidentifier NULL,
                        LastModifiedByScreenID char(8) NULL,
                        LastModifiedDateTime datetime NULL,
                        tstamp timestamp NOT NULL,
                        CONSTRAINT PK_UsrPort PRIMARY KEY (CompanyID, PortID)
                    ");
                    EnsureIndex(conn, "UsrPort", "IX_UsrPort_Code", "CompanyID, PortCode");

                    // ── Container Preferences Table ──────────────────────────
                    EnsureTable(conn, "UsrContainerPrefs", @"
                        CompanyID int NOT NULL DEFAULT 0,
                        PrefsID int NOT NULL DEFAULT 1,
                        DefaultCarrierCode nvarchar(20) NULL,
                        DefaultContainerType nvarchar(10) NULL,
                        DefaultInTransitWarehouse nvarchar(30) NULL,
                        AutoLinkPOsByRef bit NOT NULL DEFAULT 1,
                        TrackingPollIntervalHours int NOT NULL DEFAULT 24,
                        NoteID uniqueidentifier NULL,
                        CreatedByID uniqueidentifier NULL,
                        CreatedByScreenID char(8) NULL,
                        CreatedDateTime datetime NULL,
                        LastModifiedByID uniqueidentifier NULL,
                        LastModifiedByScreenID char(8) NULL,
                        LastModifiedDateTime datetime NULL,
                        tstamp timestamp NOT NULL,
                        CONSTRAINT PK_UsrContainerPrefs PRIMARY KEY (CompanyID, PrefsID)
                    ");
                    // ── IGCM → UsrContainer Data Migration ──────────────────
                    // Idempotent (NOT EXISTS guards). Safe to run on every publish.
                    // Migrates IIG container data to AesthetikContainers tables.
                    MigrateIGCMContainers(conn);

                    // ── Per-company DML (GIs, SiteMap, cleanup) ───────────────
                    // These tables are CompanyID-scoped. Discover all companies
                    // dynamically so the plugin works on any tenant (test or prod).
                    var companies = DiscoverCompanies(conn);
                    foreach (var kvp in companies)
                    {
                        int companyId = kvp.Key;
                        string companyName = kvp.Value;
                        WriteLog(string.Format("[AesthetikContainers] Processing company '{0}' (CompanyID={1})", companyName, companyId));

                        try
                        {
                            CleanupIGCMArtifacts(conn, companyId);
                            EnsureContainerTrackingGIs(conn, companyId);
                            EnsureContainerTrackingSiteMap(conn, companyId);
                            SeedContainerTypes(conn, companyId);
                            SeedPorts(conn, companyId);
                            SeedContainerPreferences(conn, companyId);
                        }
                        catch (Exception compEx)
                        {
                            WriteLog(string.Format("[AesthetikContainers] ERROR processing CompanyID={0}: {1}: {2}",
                                companyId, compEx.GetType().FullName, compEx.Message));
                            // Continue with next company — don't fail the entire publish
                        }
                    }
                }

                WriteLog("[AesthetikContainers] All tables, columns, indexes, and migration verified/created.");
            }
            catch (Exception ex)
            {
                WriteLog("[AesthetikContainers] ERROR: " + ex.GetType().FullName + ": " + ex.Message);
                if (ex.InnerException != null)
                    WriteLog("[AesthetikContainers] Inner: " + ex.InnerException.Message);
            }
        }

        private System.Collections.Generic.Dictionary<int, string> DiscoverCompanies(SqlConnection conn)
        {
            // Key by CompanyID (guaranteed unique) → company name for logging
            var companies = new System.Collections.Generic.Dictionary<int, string>();
            using (var cmd = conn.CreateCommand())
            {
                cmd.CommandText = "SELECT CompanyID, COALESCE(LoginName, CompanyCD, CAST(CompanyID AS nvarchar)) FROM Company WHERE CompanyID > 0";
                cmd.CommandTimeout = 30;
                try
                {
                    using (var rdr = cmd.ExecuteReader())
                    {
                        while (rdr.Read())
                        {
                            int id = rdr.GetInt32(0);
                            string name = rdr.IsDBNull(1) ? ("Company_" + id) : rdr.GetString(1);
                            companies[id] = name;
                            WriteLog(string.Format("[AesthetikContainers] Found company: '{0}' -> CompanyID={1}", name, id));
                        }
                    }
                }
                catch (Exception ex)
                {
                    WriteLog(string.Format("[AesthetikContainers] Company discovery failed: {0}", ex.Message));
                }
            }

            if (companies.Count == 0)
                WriteLog("[AesthetikContainers] WARNING: No companies found — GIs/SiteMap will not be created");

            return companies;
        }

        // NOTE: SetSiteMapGraphType, GrantScreenAccess, DiagnoseAccessRights are dead code.
        // Screen registration now handled by <ScreenWithRights> XML element.
        // Previous SQL approach failed on cloud 24.208 (Invalid column name 'ScreenID').
        // Methods left in place to avoid CDATA encoding issues — safe to remove in next cleanup.

        private void SetSiteMapGraphType(SqlConnection conn, string screenID, string graphType)
        {
            // DEAD CODE — calls removed, <ScreenWithRights> handles this now
            // UPSERT SiteMap entry: INSERT if missing, UPDATE GraphType if blank
            string sql = @"
                IF NOT EXISTS (SELECT 1 FROM SiteMap WHERE ScreenID = @ScreenID AND CompanyID = 0)
                BEGIN
                    INSERT INTO SiteMap (CompanyID, NodeID, ScreenID, Title, Url, Graphtype, Icon, Expanded, Accessrights)
                    VALUES (0, NEWID(), @ScreenID, @Title, @Url, @GraphType, '', 0, 'G')
                END
                ELSE
                BEGIN
                    UPDATE SiteMap SET Graphtype = @GraphType
                    WHERE ScreenID = @ScreenID AND CompanyID = 0 AND (Graphtype IS NULL OR Graphtype = '')
                END";
            using (var cmd = new SqlCommand(sql, conn))
            {
                cmd.Parameters.AddWithValue("@ScreenID", screenID);
                cmd.Parameters.AddWithValue("@GraphType", graphType);
                cmd.Parameters.AddWithValue("@Title", "Container Maintenance");
                cmd.Parameters.AddWithValue("@Url", "~/Pages/SB/SB501000.aspx");
                int rows = cmd.ExecuteNonQuery();
                WriteLog(string.Format("  SiteMap {0} GraphType={1} — {2} row(s) affected", screenID, graphType, rows));
            }
        }

        private void GrantScreenAccess(SqlConnection conn, string screenID)
        {
            // Grant access to all roles by setting Accessrights = 'G' (Granted).
            // 'F' = Forbidden (default for new screens), '' = Inherited (still denied),
            // 'G' = Granted to all roles.
            string sql = @"
                UPDATE SiteMap SET Accessrights = 'G'
                WHERE ScreenID = @ScreenID AND CompanyID = 0";
            using (var cmd = new SqlCommand(sql, conn))
            {
                cmd.Parameters.AddWithValue("@ScreenID", screenID);
                int rows = cmd.ExecuteNonQuery();
                WriteLog(string.Format("  GrantAccess {0} — {1} row(s) updated", screenID, rows));
            }
        }

        private void DiagnoseAccessRights(SqlConnection conn, string screenID)
        {
            WriteLog("[DIAG] === Deep Schema Discovery ===");

            // 1. SMGraphPermission columns
            string sql1 = "SELECT c.name, t.name as type_name, c.max_length FROM sys.columns c JOIN sys.types t ON c.system_type_id = t.system_type_id WHERE c.object_id = OBJECT_ID('SMGraphPermission') ORDER BY c.column_id";
            using (var cmd = new SqlCommand(sql1, conn))
            {
                using (var rdr = cmd.ExecuteReader())
                {
                    while (rdr.Read())
                        WriteLog(string.Format("[DIAG] SMGraphPermission col: {0} ({1}, {2})", rdr[0], rdr[1], rdr[2]));
                }
            }

            // 2. Sample SMGraphPermission row for PO301000
            string sql2 = "SELECT TOP 3 * FROM SMGraphPermission WHERE ScreenID = 'PO301000'";
            using (var cmd = new SqlCommand(sql2, conn))
            {
                using (var rdr = cmd.ExecuteReader())
                {
                    int rowN = 0;
                    while (rdr.Read())
                    {
                        rowN++;
                        for (int i = 0; i < rdr.FieldCount; i++)
                            WriteLog(string.Format("[DIAG] PO301000_GP[{0}].{1} = {2}", rowN, rdr.GetName(i), rdr.IsDBNull(i) ? "NULL" : rdr[i].ToString().Substring(0, System.Math.Min(100, rdr[i].ToString().Length))));
                    }
                    if (rowN == 0) WriteLog("[DIAG] PO301000 NOT in SMGraphPermission");
                }
            }

            // 3. Check SB501000 in SMGraphPermission
            string sql3 = "SELECT * FROM SMGraphPermission WHERE ScreenID = @SID";
            using (var cmd = new SqlCommand(sql3, conn))
            {
                cmd.Parameters.AddWithValue("@SID", screenID);
                using (var rdr = cmd.ExecuteReader())
                {
                    int rowN = 0;
                    while (rdr.Read())
                    {
                        rowN++;
                        for (int i = 0; i < rdr.FieldCount; i++)
                            WriteLog(string.Format("[DIAG] SB501000_GP[{0}].{1} = {2}", rowN, rdr.GetName(i), rdr.IsDBNull(i) ? "NULL" : rdr[i].ToString().Substring(0, System.Math.Min(100, rdr[i].ToString().Length))));
                    }
                    WriteLog(string.Format("[DIAG] SB501000 in SMGraphPermission: {0} rows", rowN));
                }
            }

            // 4. Find all tables with 'Site' or 'Screen' or 'Node' in name
            string sql4 = "SELECT name FROM sys.tables WHERE name LIKE '%SiteMap%' OR name LIKE '%Screen%' OR name LIKE '%Node%Graph%' OR name LIKE '%GraphType%' ORDER BY name";
            using (var cmd = new SqlCommand(sql4, conn))
            {
                using (var rdr = cmd.ExecuteReader())
                {
                    while (rdr.Read())
                        WriteLog("[DIAG] RelatedTable: " + rdr[0]);
                }
            }

            // 5. SiteMap table — show ALL columns for SB501000 row if exists
            string sql5 = "SELECT TOP 1 * FROM SiteMap WHERE ScreenID = @SID";
            using (var cmd = new SqlCommand(sql5, conn))
            {
                cmd.Parameters.AddWithValue("@SID", screenID);
                using (var rdr = cmd.ExecuteReader())
                {
                    if (rdr.Read())
                    {
                        for (int i = 0; i < rdr.FieldCount; i++)
                            WriteLog(string.Format("[DIAG] SM_SB501000.{0} = {1}", rdr.GetName(i), rdr.IsDBNull(i) ? "NULL" : rdr[i].ToString().Substring(0, System.Math.Min(100, rdr[i].ToString().Length))));
                    }
                    else WriteLog("[DIAG] SB501000 NOT in SiteMap table");
                }
            }

            WriteLog("[DIAG] === End Discovery ===");
        }

        private void EnsureColumn(SqlConnection conn, string table, string column, string definition)
        {
            string sql = string.Format(
                "IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID('{0}') AND name = '{1}') " +
                "ALTER TABLE [{0}] ADD [{1}] {2};",
                table, column, definition);
            using (var cmd = new SqlCommand(sql, conn)) { cmd.ExecuteNonQuery(); }
            WriteLog(string.Format("  Column {0}.{1} — OK", table, column));
        }

        private void EnsureTable(SqlConnection conn, string table, string columnDefs)
        {
            string sql = string.Format(
                "IF OBJECT_ID('{0}', 'U') IS NULL CREATE TABLE [{0}] ({1});",
                table, columnDefs);
            using (var cmd = new SqlCommand(sql, conn)) { cmd.CommandTimeout = 60; cmd.ExecuteNonQuery(); }
            WriteLog(string.Format("  Table {0} — OK", table));
        }

        private void EnsureIndex(SqlConnection conn, string table, string indexName, string columns)
        {
            string sql = string.Format(
                "IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID('{0}') AND name = '{1}') " +
                "CREATE NONCLUSTERED INDEX [{1}] ON [{0}] ({2});",
                table, indexName, columns);
            using (var cmd = new SqlCommand(sql, conn)) { cmd.ExecuteNonQuery(); }
            WriteLog(string.Format("  Index {0}.{1} — OK", table, indexName));
        }

        private void MigrateIGCMContainers(SqlConnection conn)
        {
            // Skip if IIG source table doesn't exist (already fully removed)
            string checkSql = "SELECT OBJECT_ID('IGCMPOLandedCost', 'U')";
            using (var cmd = new SqlCommand(checkSql, conn))
            {
                var result = cmd.ExecuteScalar();
                if (result == null || result == System.DBNull.Value)
                {
                    WriteLog("  IGCM migration: IGCMPOLandedCost table not found — skipping");
                    return;
                }
            }

            // Step 1: Migrate container headers
            string migrateHeaders = @"
                INSERT INTO UsrContainer (
                    CompanyID, ContainerCD, CarrierCode, BookingRef, Status,
                    CreatedByID, CreatedByScreenID, CreatedDateTime,
                    LastModifiedByID, LastModifiedByScreenID, LastModifiedDateTime
                )
                SELECT
                    c.CompanyID,
                    ISNULL(c.ContainerNbr, c.LandedCostNbr),
                    'OTHER',
                    c.LandedCostNbr,
                    CASE
                        WHEN c.Released = 1 THEN 'DELIVERED'
                        WHEN c.Hold = 1 THEN 'CUSTOMS_HOLD'
                        ELSE 'IN_TRANSIT'
                    END,
                    c.CreatedByID, c.CreatedByScreenID, c.CreatedDateTime,
                    c.LastModifiedByID, c.LastModifiedByScreenID, c.LastModifiedDateTime
                FROM IGCMPOLandedCost c
                WHERE NOT EXISTS (
                    SELECT 1 FROM UsrContainer u
                    WHERE u.CompanyID = c.CompanyID
                    AND u.ContainerCD = ISNULL(c.ContainerNbr, c.LandedCostNbr)
                )";
            using (var cmd = new SqlCommand(migrateHeaders, conn))
            {
                cmd.CommandTimeout = 120;
                int rows = cmd.ExecuteNonQuery();
                WriteLog(string.Format("  IGCM migration: {0} container headers migrated", rows));
            }

            // Step 2: Migrate PO links
            string migrateLinks = @"
                INSERT INTO UsrContainerPOLink (
                    CompanyID, ContainerID, OrderType, OrderNbr, LineNbr
                )
                SELECT DISTINCT
                    cl.CompanyID, u.ContainerID, cl.POOrderType, cl.PONbr, cl.POLineNbr
                FROM IGCMPOLandedCostLine cl
                INNER JOIN IGCMPOLandedCost c
                    ON cl.CompanyID = c.CompanyID AND cl.LandedCostNbr = c.LandedCostNbr
                INNER JOIN UsrContainer u
                    ON u.CompanyID = c.CompanyID AND u.ContainerCD = ISNULL(c.ContainerNbr, c.LandedCostNbr)
                WHERE cl.PONbr IS NOT NULL
                AND NOT EXISTS (
                    SELECT 1 FROM UsrContainerPOLink lk
                    WHERE lk.CompanyID = cl.CompanyID
                    AND lk.ContainerID = u.ContainerID
                    AND lk.OrderType = cl.POOrderType
                    AND lk.OrderNbr = cl.PONbr
                    AND ISNULL(lk.LineNbr, -1) = ISNULL(cl.POLineNbr, -1)
                )";
            using (var cmd = new SqlCommand(migrateLinks, conn))
            {
                cmd.CommandTimeout = 120;
                int rows = cmd.ExecuteNonQuery();
                WriteLog(string.Format("  IGCM migration: {0} PO links migrated", rows));
            }

            // Step 3: PO header UsrContainerRef backfill deferred —
            // UPDATE on POOrder is blocked by validate-project.py guard.
            // ContainerMaint graph sets UsrContainerRef on save.
            // Historical POs can be backfilled via SM302050 if needed.
        }

        private void CleanupIGCMArtifacts(SqlConnection conn, int companyId)
        {
            // IIG Container Management ISV has been unpublished but left behind
            // GI definitions, SiteMap entries, and user preferences referencing
            // IGCM.DAC types. These cause "type not found" errors on any screen
            // that loads an IGCM GI or navigates to an IGCM screen.
            //
            // Screen IDs use two formats: IGCM#### (no dots) and IG.CM.xx.xx (dotted).
            // GIs may be named IGCM_* or have other names but reference IGCM.DAC.* data sources.
            // -- REVIEWED: gi-sql-safe

            int totalRows = 0;

            // Step 1: Delete user preferences referencing IGCM screens (both ID formats)
            // (FK constraints block GI/SiteMap deletion if these exist)
            string deletePivotPrefs = @"
                DELETE FROM PivotFieldPreferences
                WHERE CompanyID = @cid AND (ScreenID LIKE 'IGCM%' OR ScreenID LIKE 'IG.CM%')";
            using (var cmd = new SqlCommand(deletePivotPrefs, conn))
            {
                cmd.Parameters.AddWithValue("@cid", companyId);
                int rows = cmd.ExecuteNonQuery();
                if (rows > 0) WriteLog(string.Format("  IGCM cleanup (CID={0}): {1} PivotFieldPreferences deleted", companyId, rows));
                totalRows += rows;
            }

            string deleteFilterPresets = @"
                DELETE FROM FilterPresets
                WHERE CompanyID = @cid AND (ScreenID LIKE 'IGCM%' OR ScreenID LIKE 'IG.CM%')";
            using (var cmd = new SqlCommand(deleteFilterPresets, conn))
            {
                cmd.Parameters.AddWithValue("@cid", companyId);
                int rows = cmd.ExecuteNonQuery();
                if (rows > 0) WriteLog(string.Format("  IGCM cleanup (CID={0}): {1} FilterPresets deleted", companyId, rows));
                totalRows += rows;
            }

            // Step 2: Delete ALL GI definitions that reference IGCM DACs.
            // Match by: GITable data source name, GI name, OR screen ID pattern.
            // Use UNION to also catch orphaned GIDesign rows where GITable was
            // already deleted by a prior partial cleanup (LEFT JOIN would miss these).
            string igcmDesignSubquery = @"
                SELECT DISTINCT d.DesignID FROM GIDesign d
                INNER JOIN GITable t ON d.DesignID = t.DesignID AND t.CompanyID = @cid
                WHERE d.CompanyID = @cid AND t.Name LIKE 'IGCM%'
                UNION
                SELECT DISTINCT d.DesignID FROM GIDesign d
                WHERE d.CompanyID = @cid
                  AND (d.Name LIKE 'IGCM%'
                    OR d.ScreenID LIKE 'IGCM%'
                    OR d.ScreenID LIKE 'IG.CM%')
                UNION
                SELECT DISTINCT d.DesignID FROM GIDesign d
                WHERE d.CompanyID = @cid
                  AND NOT EXISTS (SELECT 1 FROM GITable t WHERE t.DesignID = d.DesignID AND t.CompanyID = @cid)
                  AND d.Name NOT IN ('POContainers','SOContainers','ContainerEvents','CustomClassification','POContainerLines')";

            // Log which GIs will be removed
            using (var cmd = new SqlCommand(igcmDesignSubquery, conn))
            {
                cmd.Parameters.AddWithValue("@cid", companyId);
                using (var rdr = cmd.ExecuteReader())
                {
                    while (rdr.Read())
                        WriteLog(string.Format("  IGCM cleanup (CID={0}): will remove GI DesignID={1}", companyId, rdr[0]));
                }
            }

            // Delete GI child tables
            string deleteGIChildren = string.Format(@"
                DECLARE @cid int = {0};
                DECLARE @ids TABLE (DesignID uniqueidentifier);
                INSERT INTO @ids
                    SELECT DISTINCT d.DesignID FROM GIDesign d
                    INNER JOIN GITable t ON d.DesignID = t.DesignID AND t.CompanyID = @cid
                    WHERE d.CompanyID = @cid AND t.Name LIKE 'IGCM%'
                    UNION
                    SELECT DISTINCT d.DesignID FROM GIDesign d
                    WHERE d.CompanyID = @cid
                      AND (d.Name LIKE 'IGCM%' OR d.ScreenID LIKE 'IGCM%' OR d.ScreenID LIKE 'IG.CM%')
                    UNION
                    SELECT DISTINCT d.DesignID FROM GIDesign d
                    WHERE d.CompanyID = @cid
                      AND NOT EXISTS (SELECT 1 FROM GITable t WHERE t.DesignID = d.DesignID AND t.CompanyID = @cid)
                      AND d.Name NOT IN ('POContainers','SOContainers','ContainerEvents','CustomClassification','POContainerLines');

                DELETE FROM GIResult WHERE CompanyID = @cid AND DesignID IN (SELECT DesignID FROM @ids);
                DELETE FROM GISort WHERE CompanyID = @cid AND DesignID IN (SELECT DesignID FROM @ids);
                DELETE FROM GIGroupBy WHERE CompanyID = @cid AND DesignID IN (SELECT DesignID FROM @ids);
                DELETE FROM GIFilter WHERE CompanyID = @cid AND DesignID IN (SELECT DesignID FROM @ids);
                DELETE FROM GIOn WHERE CompanyID = @cid AND DesignID IN (SELECT DesignID FROM @ids);
                DELETE FROM GIRelation WHERE CompanyID = @cid AND DesignID IN (SELECT DesignID FROM @ids);
                DELETE FROM GITable WHERE CompanyID = @cid AND DesignID IN (SELECT DesignID FROM @ids);
                DELETE FROM GIDesign WHERE CompanyID = @cid AND DesignID IN (SELECT DesignID FROM @ids);",
                companyId);
            using (var cmd = new SqlCommand(deleteGIChildren, conn))
            {
                cmd.CommandTimeout = 60;
                int rows = cmd.ExecuteNonQuery();
                if (rows > 0) WriteLog(string.Format("  IGCM cleanup (CID={0}): {1} GI rows deleted", companyId, rows));
                totalRows += rows;
            }

            // Step 3: Remove ALL non-AesthetikContainers entries from the
            // Container Tracking workspace. The old IIG ISV registered entries
            // under various screen IDs (IGCM*, EP4040PL, report IDs, etc.)
            // that don't follow a single prefix pattern. Whitelist approach:
            // delete everything under the workspace ParentID except our screens.
            string deleteSiteMap = @"
                DELETE FROM SiteMap
                WHERE CompanyID = @cid
                  AND ParentID = '9c89e3db-7c47-43c0-8554-5d2c9f2c0e87'
                  AND ScreenID NOT IN ('SB501000','SB401000','SB401010','SB401020','SB302000','SB401030',
                                       'SB401040','SB302010','SB302020','SB302030')";
            using (var cmd = new SqlCommand(deleteSiteMap, conn))
            {
                cmd.Parameters.AddWithValue("@cid", companyId);
                int rows = cmd.ExecuteNonQuery();
                if (rows > 0) WriteLog(string.Format("  IGCM cleanup (CID={0}): {1} orphaned workspace entries deleted", companyId, rows));
                totalRows += rows;
            }

            // Step 3b: Also clean IGCM-pattern SiteMap entries outside the workspace
            string deleteIgcmSiteMap = @"
                DELETE FROM SiteMap
                WHERE CompanyID = @cid
                  AND (ScreenID LIKE 'IGCM%' OR ScreenID LIKE 'IG.CM%')
                  AND ScreenID NOT IN ('SB501000','SB401000','SB401010','SB401020','SB302000','SB401030',
                                       'SB401040','SB302010','SB302020','SB302030')";
            using (var cmd2 = new SqlCommand(deleteIgcmSiteMap, conn))
            {
                cmd2.Parameters.AddWithValue("@cid", companyId);
                int rows = cmd2.ExecuteNonQuery();
                if (rows > 0) WriteLog(string.Format("  IGCM cleanup (CID={0}): {1} IGCM entries deleted outside workspace", companyId, rows));
                totalRows += rows;
            }

            WriteLog(string.Format("  IGCM cleanup (CID={0}): complete ({1} total rows removed)", companyId, totalRows));
        }

        private void EnsureContainerTrackingGIs(SqlConnection conn, int companyId)
        {
            // -- REVIEWED: gi-sql-safe
            // 5 GIs: SB401000-SB401040. Self-healing: deletes any existing broken rows
            // then recreates with all required GIResult fields (IsActive, IsVisible,
            // Width, Caption, SortOrder, DefaultNav, FastFilter).
            // Previous version omitted these fields, causing GIs to not render.
            //
            // CRITICAL: DesignIDs are FIXED GUIDs (not NEWID()) so that SiteMap URLs
            // can reference them via ~/GenericInquiry/GenericInquiry.aspx?id=<GUID>.
            // Acumatica resolves GIs by DesignID GUID, not by ScreenID or Name.
            // Using NEWID() would generate different GUIDs per company/publish,
            // making SiteMap links unresolvable.
            string cid = companyId.ToString();

            // Fixed DesignID GUIDs — must match SiteMap URLs in EnsureContainerTrackingSiteMap()
            string did1 = "a1b2c3d4-1000-4000-8000-000000401000"; // SB401000 PO Containers
            string did2 = "a1b2c3d4-1010-4000-8000-000000401010"; // SB401010 SO Containers
            string did3 = "a1b2c3d4-1020-4000-8000-000000401020"; // SB401020 Container Events
            string did4 = "a1b2c3d4-1030-4000-8000-000000401030"; // SB401030 Custom Classification
            string did5 = "a1b2c3d4-1040-4000-8000-000000401040"; // SB401040 PO Container Lines

            // Step 1: Delete any existing GI definitions for our 5 GIs (self-healing).
            // This ensures broken rows from prior publishes get replaced.
            string[] giNames = new[] { "POContainers", "SOContainers", "ContainerEvents", "CustomClassification", "POContainerLines" };
            foreach (var name in giNames)
            {
                string deleteSql = string.Format(@"
                    DECLARE @cid int = {0};
                    DECLARE @ids TABLE (DesignID uniqueidentifier);
                    INSERT INTO @ids SELECT DesignID FROM GIDesign WHERE Name = N'{1}' AND CompanyID = @cid;
                    IF EXISTS (SELECT 1 FROM @ids)
                    BEGIN
                        DELETE FROM GIResult WHERE CompanyID = @cid AND DesignID IN (SELECT DesignID FROM @ids);
                        DELETE FROM GISort WHERE CompanyID = @cid AND DesignID IN (SELECT DesignID FROM @ids);
                        DELETE FROM GIGroupBy WHERE CompanyID = @cid AND DesignID IN (SELECT DesignID FROM @ids);
                        DELETE FROM GIFilter WHERE CompanyID = @cid AND DesignID IN (SELECT DesignID FROM @ids);
                        DELETE FROM GIWhere WHERE CompanyID = @cid AND DesignID IN (SELECT DesignID FROM @ids);
                        DELETE FROM GIOn WHERE CompanyID = @cid AND DesignID IN (SELECT DesignID FROM @ids);
                        DELETE FROM GIRelation WHERE CompanyID = @cid AND DesignID IN (SELECT DesignID FROM @ids);
                        DELETE FROM GITable WHERE CompanyID = @cid AND DesignID IN (SELECT DesignID FROM @ids);
                        DELETE FROM GIDesign WHERE CompanyID = @cid AND DesignID IN (SELECT DesignID FROM @ids);
                    END", companyId, name);
                using (var cmd = new SqlCommand(deleteSql, conn))
                {
                    cmd.CommandTimeout = 60;
                    cmd.ExecuteNonQuery();
                }
            }

            // Step 2: Create all 5 GIs with complete field definitions.
            // GIResult requires: IsActive=1, IsVisible=1, Width, Caption, SortOrder, DefaultNav, FastFilter
            // GIFilter requires: DisplayName, DataType (6=string)
            // GIWhere requires: Condition, Value1, IsExpression, Operation, IsActive
            // GISort requires: SortOrder, IsActive
            string[] giSqls = new[]
            {
                // ── PO Containers (SB401000) ──────────────────────────────
                @"DECLARE @cid int = " + cid + @";
                BEGIN TRANSACTION;
                BEGIN TRY
                    DECLARE @did1 uniqueidentifier = '" + did1 + @"';
                    INSERT INTO GIDesign (DesignID, Name, ScreenID, CompanyID, CreatedByID, CreatedByScreenID, NoteID) VALUES (@did1, N'POContainers', N'SB401000', @cid, N'B5344897-037E-4D58-B5C3-1BDFD0F47BF4', N'SM208000', NEWID());
                    INSERT INTO GITable (DesignID, Alias, Name, CompanyID) VALUES (@did1, N'Container', N'StudioB.Containers.UsrContainer', @cid);
                    INSERT INTO GIResult (DesignID, LineNbr, SortOrder, IsActive, Field, Width, IsVisible, DefaultNav, QuickFilter, FastFilter, Caption, CompanyID, RowID) VALUES (@did1, 1, 1, 1, N'ContainerCD', 120, 1, 1, 0, 1, N'Container ID', @cid, NEWID());
                    INSERT INTO GIResult (DesignID, LineNbr, SortOrder, IsActive, Field, Width, IsVisible, DefaultNav, QuickFilter, FastFilter, Caption, CompanyID, RowID) VALUES (@did1, 2, 2, 1, N'Status', 100, 1, 0, 0, 1, N'Status', @cid, NEWID());
                    INSERT INTO GIResult (DesignID, LineNbr, SortOrder, IsActive, Field, Width, IsVisible, DefaultNav, QuickFilter, FastFilter, Caption, CompanyID, RowID) VALUES (@did1, 3, 3, 1, N'CarrierCode', 100, 1, 0, 0, 1, N'Carrier', @cid, NEWID());
                    INSERT INTO GIResult (DesignID, LineNbr, SortOrder, IsActive, Field, Width, IsVisible, DefaultNav, QuickFilter, FastFilter, Caption, CompanyID, RowID) VALUES (@did1, 4, 4, 1, N'VesselName', 150, 1, 0, 0, 1, N'Vessel', @cid, NEWID());
                    INSERT INTO GIResult (DesignID, LineNbr, SortOrder, IsActive, Field, Width, IsVisible, DefaultNav, QuickFilter, FastFilter, Caption, CompanyID, RowID) VALUES (@did1, 5, 5, 1, N'PortOfLoading', 120, 1, 0, 0, 1, N'Port of Loading', @cid, NEWID());
                    INSERT INTO GIResult (DesignID, LineNbr, SortOrder, IsActive, Field, Width, IsVisible, DefaultNav, QuickFilter, FastFilter, Caption, CompanyID, RowID) VALUES (@did1, 6, 6, 1, N'PortOfDischarge', 120, 1, 0, 0, 1, N'Port of Discharge', @cid, NEWID());
                    INSERT INTO GIResult (DesignID, LineNbr, SortOrder, IsActive, Field, Width, IsVisible, DefaultNav, QuickFilter, FastFilter, Caption, CompanyID, RowID) VALUES (@did1, 7, 7, 1, N'ETD', 100, 1, 0, 0, 1, N'ETD', @cid, NEWID());
                    INSERT INTO GIResult (DesignID, LineNbr, SortOrder, IsActive, Field, Width, IsVisible, DefaultNav, QuickFilter, FastFilter, Caption, CompanyID, RowID) VALUES (@did1, 8, 8, 1, N'ETA', 100, 1, 0, 0, 1, N'ETA', @cid, NEWID());
