                    INSERT INTO GIFilter (DesignID, LineNbr, Name, DisplayName, DataType, IsExpression, CompanyID) VALUES (@did1, 1, N'StatusFilter', N'Status', 6, 0, @cid);
                    INSERT INTO GIFilter (DesignID, LineNbr, Name, DisplayName, DataType, IsExpression, CompanyID) VALUES (@did1, 2, N'CarrierFilter', N'Carrier', 6, 0, @cid);
                    INSERT INTO GIWhere (DesignID, LineNbr, IsActive, DataFieldName, Condition, Value1, IsExpression, Operation, CompanyID) VALUES (@did1, 1, 1, N'Container.Status', N'E ', N'@StatusFilter', 0, N'A', @cid);
                    INSERT INTO GIWhere (DesignID, LineNbr, IsActive, DataFieldName, Condition, Value1, IsExpression, Operation, CompanyID) VALUES (@did1, 2, 1, N'Container.CarrierCode', N'E ', N'@CarrierFilter', 0, N'A', @cid);
